        self.value = value

    def __repr__(self):
        return str(self.value)


class BinaryOperator(Node):
    """
    A node that represents a binary operator.
    """

    def __init__(self, left, right, op):
        self.left = left
        self.right = right
        self.op = op

    def __repr__(self):
        return u"{} {} {}".format(self.left, self.op, self.right)


