    """
    A node that represents a logical or operator.
    """

    def __init__(self, left, right):
        super(Or, self).__init__(left, right, "|")


class And(BinaryOperator):
    """
    A node that represents a logical and operator.
    """

    def __init__(self, left, right):
        super(And, self).__init__(left, right, "&")


class Compare(BinaryOperator):
    """
    A node that represents a comparison operator.
    """

    EQ = "="
    NE = "!="
    LT = "<"
    GT = ">"
    LTE = "<="
    GTE = ">="

    def __init__(self, left, right, operator):
        if operator not in (self.EQ, self.NE, self.LT, self.GT,
                            self.LTE, self.GTE):
            raise ValueError("Operator '{}' is not valid.".format(operator))
        super(Compare, self).__init__(left, right, operator)


